/**
 * Stock Health weekly mails as Email Templates (Settings → Email Templates): keys, default
 * Subject / Body and placeholders. Plain strings only — the tables are generated by
 * lib/stock-health/summary-mail-html.ts and dropped into the {{…Html}} placeholders.
 * To / CC come from the saved template (no recipients by default, so nothing is sent
 * until someone adds them).
 */

/** Mail 2 — Monday 9:00 AM. */
export const STOCK_AVAILABILITY_STATUS_WEEKLY_KEY = "stock_availability_status_weekly";
/** Mail 1 — Tuesday 9:00 AM. */
export const STOCK_HEALTH_WEEKLY_SUMMARY_KEY = "stock_health_weekly_summary";

const P = "font-family:Arial, Helvetica, sans-serif;font-size:14px;color:#0f172a;margin:0";
const NOTE = "font-family:Arial, Helvetica, sans-serif;font-size:12px;color:#64748b;margin:6px 0 0";

export const STOCK_HEALTH_WEEKLY_SUMMARY_TEMPLATE = {
  key: STOCK_HEALTH_WEEKLY_SUMMARY_KEY,
  name: "Stock Health Weekly Summary",
  subject: "Stock Health Summary - Weekly Summary - {{reportDate}}",
  bodyHtml: `<p style="${P} 0 4px">Dear team,</p>
<p style="${P}">Here is the Stock Health Weekly Summary for {{reportDate}}.</p>
<p style="${NOTE}">Live ERP stock as of {{stockAsOf}} (excluded SKUs and website drafts with no stock left out).</p>
{{weeklySummaryTableHtml}}
{{discontinueTrackingHtml}}
{{dataSourcesHtml}}`,
  placeholders: [
    "companyName",
    "reportDate",
    "stockAsOf",
    "generatedAt",
    "weeklySummaryTableHtml",
    "discontinueTrackingHtml",
    "dataSourcesHtml",
  ],
};

export const STOCK_AVAILABILITY_STATUS_WEEKLY_TEMPLATE = {
  key: STOCK_AVAILABILITY_STATUS_WEEKLY_KEY,
  name: "Stock Availability Status",
  subject: "Stock Health Summary - Stock Availability Status - Overall - {{reportDate}}",
  bodyHtml: `<p style="${P} 0 4px">Dear team,</p>
<p style="${P}">Here is the Stock Availability Status for {{reportDate}}.</p>
<p style="${NOTE}">Live ERP stock as of {{stockAsOf}} (excluded SKUs and website drafts with no stock left out).</p>
{{overallTableHtml}}
{{companyWiseTableHtml}}
{{outOfStockTableHtml}}
{{dataSourcesHtml}}`,
  placeholders: [
    "companyName",
    "reportDate",
    "stockAsOf",
    "generatedAt",
    "overallTableHtml",
    "companyWiseTableHtml",
    "outOfStockTableHtml",
    "dataSourcesHtml",
  ],
};
